check_code:
opts={'A':'RX59','B':'QY57','C':'PY59','D':'QX58'}
def nxt():
    return chr(ord('N')+2)+chr(ord('V')+3)+str(62-3)
r=nxt()
assert r==opts['C']
for k in 'ABD': assert r!=opts[k]

opts={'A':'RCN','B':'RCM','C':'JCN','D':'JCM'}
def f(s): return ''.join(chr((ord(c)-65-9)%26+65) for c in s)
assert f('CRW')=='TIN' and f('DOZ')=='UFQ'
r=f('ALW')
assert r==opts['A']
for k in 'BCD': assert r!=opts[k]

opts={'A':'SQPN','B':'YWVT','C':'NLKI','D':'WVTS'}
def g(s): return tuple(ord(s[i])-ord(s[i+1]) for i in range(3))
odd=[k for k,v in opts.items() if sum(g(v)==g(w) for w in opts.values())==1]
assert odd==['D']

