rel={'A':'covers','B':'whole-part','C':'whole-part','D':'whole-part'}
odd=[k for k,v in rel.items() if list(rel.values()).count(v)==1]
assert odd==['A']

pat='Z_A_Z__ZA_Z_'
opts={'A':'ZZAZZA','B':'AZAZAZ','C':'ZZZAAA','D':'AZZAZZ'}
def fill(o):
    it=iter(o); return ''.join(next(it) if c=='_' else c for c in pat)
ok=[k for k,v in opts.items() if fill(v)=='ZZAZZAZZAZZA']
assert ok==['A']

